cssCode:
.morph-loader {
  width: 80px; height: 80px;
  background: #00d2ff;
  animation: morphingAnim 2s infinite ease-in-out;
}
@keyframes morphingAnim {
  0%   { border-radius: 10px; transform: rotate(0deg); }
  25%  { border-radius: 50%; background: #ff007f; transform: rotate(90deg); }
  50%  { border-radius: 10px; background: #6c63ff; transform: rotate(180deg); }
  75%  { border-radius: 50%; background: #00ffcc; transform: rotate(270deg); }
  100% { border-radius: 10px; background: #00d2ff; transform: rotate(360deg); }
}

